ALTER TABLE "Company" ADD COLUMN "poolSubcompanyRewards" BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE "SubCompany" (
 "id" SERIAL PRIMARY KEY,
 "companyId" INTEGER NOT NULL REFERENCES "Company"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
 "name" TEXT NOT NULL,
 "nameKey" TEXT NOT NULL,
 "group" TEXT NOT NULL,
 "domain" TEXT,
 "rewardCreditCents" INTEGER NOT NULL DEFAULT 0,
 "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX "SubCompany_companyId_nameKey_key" ON "SubCompany"("companyId", "nameKey");
CREATE INDEX "SubCompany_companyId_idx" ON "SubCompany"("companyId");
ALTER TABLE "User" ADD COLUMN "subCompanyId" INTEGER REFERENCES "SubCompany"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD COLUMN "subCompanyId" INTEGER REFERENCES "SubCompany"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE INDEX "User_subCompanyId_idx" ON "User"("subCompanyId");
CREATE INDEX "Booking_subCompanyId_idx" ON "Booking"("subCompanyId");
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM "Company" WHERE "nameKey"='caymanislandsgovernment' AND "domain"='gov.ky' AND "archivedAt" IS NULL) THEN RAISE EXCEPTION 'Government company identity needs administrator review'; END IF;
END $$;
UPDATE "Company" SET "poolSubcompanyRewards"=false WHERE "nameKey"='caymanislandsgovernment';
